#### `ApiKeyStatsPanel` 结构示意：

```tsx
function ApiKeyStatsPanel({ userId, keyId, keyName }: { userId: number; keyId: number; keyName: string }) {
  const [days, setDays] = useState(7)
  const [stats, setStats] = useState<ApiKeyCallStats | null>(null)
  const [trends, setTrends] = useState<ApiKeyCallTrendPoint[]>([])
  const [logs, setLogs] = useState<CallLogItem[]>([])
  const [logPage, setLogPage] = useState(1)
  const [logTotal, setLogTotal] = useState(0)

useEffect(() => {
    // 并发请求 3 个 API
    const end = new Date(); const start = new Date(); start.setDate(start.getDate() - days)
    Promise.all([
      get(`/api/v1/admin/users/${userId}/api-keys/${keyId}/call-stats`, { startDate: start, endDate: end }),
      get(`/api/v1/admin/users/${userId}/api-keys/${keyId}/call-trends`, { days }),
      get(`/api/v1/admin/users/${userId}/api-keys/${keyId}/call-logs`, { page: logPage, startDate: start, endDate: end }),
    ]).then(([s, t, l]) => {
      setStats(s); setTrends(t.series); setLogs(l.list); setLogTotal(l.total)
    })
  }, [userId, keyId, days, logPage])

  return (
    <div className="bg-slate-50 rounded-lg p-4 ml-4 my-2 space-y-4 border border-slate-200">
      {/* Header with key name + date range */}
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-semibold">🔑 {keyName}</h4>
        <select>...</select>
      </div>
      {/* Summary cards */}
      <div className="grid grid-cols-4 gap-2">
        <StatCard label="总调用" value={...} />
        <StatCard label="总Token" value={...} />
        <StatCard label="总费用" value={...} />
        <StatCard label="成功率" value={...} />
      </div>
      {/* Trend line chart */}
      <MiniLineChart data={trends} ... />
      {/* Detail call log table */}
      <table>...<table>
    </div>
  )
}
```

