app.get("/api/v1/admin/real-name/file/:userId/:filename", {
  preHandler: [authenticateJWT, requireRole("admin", "super_admin")],
  handler: async (request, reply) => {
    const { userId, filename } = request.params as any;

    // 安全校验：防止路径穿越
    if (filename.includes("..") || filename.includes("/") || filename.includes("\\")) {
      reply.status(400).send({ code: 400, data: null, message: "非法文件名" });
      return;
    }

    const filePath = path.join(config.upload.dir, "real-name", String(userId), filename);

    // 检查文件是否存在
    if (!fs.existsSync(filePath)) {
      reply.status(404).send({ code: 404, data: null, message: "文件不存在" });
      return;
    }

    // 根据扩展名设置 Content-Type
    const ext = path.extname(filename).toLowerCase();
    const mimeMap: Record<string, string> = {
      ".jpg": "image/jpeg",
      ".jpeg": "image/jpeg",
      ".png": "image/png",
      ".pdf": "application/pdf",
    };

reply.type(mimeMap[ext] || "application/octet-stream");
    reply.send(fs.createReadStream(filePath));
  },
});
