**② 新增 `settleCommissions()` 结算函数（agent-service.ts）**

```typescript
async function settleCommissions(agentId?: number) {
  const conditions = [eq(commissionLogs.status, "pending")];
  if (agentId) conditions.push(eq(commissionLogs.agentId, agentId));

  // 查出所有待结算记录
  const pendingList = await db.select().from(commissionLogs).where(and(...conditions));

  // 按代理商分组汇总
  const agentMap = new Map<number, Decimal>();
  for (const c of pendingList) {
    agentMap.set(c.agentId, (agentMap.get(c.agentId) ?? 0) + Number(c.commissionAmount));
  }

  // 事务：更新状态 + 更新余额
  await db.transaction(async (tx) => {
    // 更新佣金状态为 settled
    await tx.update(commissionLogs).set({ status: "settled", settledAt: new Date() })
      .where(and(...conditions));
    // 累加代理商已结算余额
    for (const [aid, amount] of agentMap) {
      await tx.update(agents).set({
        settledCommission: sql`settled_commission + ${amount}`
      }).where(eq(agents.id, aid));
    }
  });
}
```

