```typescript
export async function settleCommissions(agentId?: number): Promise<number> {
  let totalSettled = 0;
  const BATCH_SIZE = 1000;

  while (true) {
    // 每次只取 1000 条，而不是全部
    const batch = await db
      .select({ id, agentId, commissionAmount })
      .from(commissionLogs)
      .where(and(...conditions))
      .limit(BATCH_SIZE)     // ← 关键：加 LIMIT
      .for('update')         // ← 加锁防止并发
      .skip(0);              // 从头部取

    if (batch.length === 0) break;

    // 在事务里处理这一批
    await db.transaction(async (tx) => {
      const ids = batch.map(r => r.id);
      await tx.update(commissionLogs).set({ status: 'settled', settledAt: new Date() })
        .where(inArray(commissionLogs.id, ids));
      // 更新 agent 余额
    });

    totalSettled += batch.length;
  }

return totalSettled;
}
```

**凭证号生成也改成批量 UPDATE，不要逐条循环。**

