**`deleteAgent()` 伪代码**：

```typescript
export async function deleteAgent(operatorId: number, agentId: number) {
  const db = getDb();

const [agent] = await db
    .select({ id: agents.id, userId: agents.userId })
    .from(agents)
    .where(eq(agents.id, agentId))
    .limit(1);
  if (!agent) throw new AppError("AGENT_NOT_FOUND", "代理商不存在", 404);

  // 检查未结清的佣金或提现
  const [pending] = await db
    .select({ count: sql<number>`count(*)` })
    .from(commissionLogs)
    .where(and(
      eq(commissionLogs.agentId, agentId),
      eq(commissionLogs.status, "pending"),
    ))
    .limit(1);
  if (Number(pending?.count ?? 0) > 0) {
    throw new AppError("HAS_PENDING_COMMISSION", "该代理商有待结算佣金，请先结算再删除", 400);
  }

  return await db.transaction(async (tx) => {
    const [user] = await tx
      .select({ role: users.role })
      .from(users)
      .where(eq(users.id, agent.userId))
      .limit(1);

    // 重置用户角色
    await tx.update(users)
      .set({ role: "user" })
      .where(eq(users.id, agent.userId));

// 记录角色变更历史
    await tx.insert(userRoleHistory).values({
      userId: agent.userId,
      oldRole: user!.role,
      newRole: "user",
      operatorId,
      reason: "管理员删除代理商身份",
    });

    // 删除代理商（CASCADE 会清理 agent_clients, commission_rules, withdraw_orders）
    await tx.delete(agents).where(eq(agents.id, agentId));

    // 审计日志
    await tx.insert(auditLogs).values({
      operatorId,
      action: "agent_update",
      targetType: "user",
      targetId: agent.userId,
      before: { role: user!.role, isAgent: true },
      after: { role: "user", isAgent: false },
      description: `删除代理商 #${agentId} 身份，用户 #${agent.userId} 降级为普通用户`,
    });

    return { deleted: true, userId: agent.userId };
  });
}
```

